function parseWifi(payload) {
  const out = { ssid: '', password: '', security: '', hidden: 'false' };
  if (payload.startsWith('WIFI:')) {
    const names = { S: 'ssid', P: 'password', T: 'security', H: 'hidden' };
    let key = '';
    let value = '';
    let inValue = false;
    let escaped = false;
    for (const ch of payload.slice(5)) {
      if (escaped) {
        value += ch;
        escaped = false;
      } else if (ch === '\\') {
        escaped = true;
      } else if (!inValue) {
        if (ch === ':') inValue = true;
        else if (ch !== ';') key += ch;
      } else if (ch === ';') {
        const name = names[key.trim().toUpperCase()];
        const quoted = value.length >= 2 && value.startsWith('"') && value.endsWith('"');
        if (name) out[name] = quoted ? value.slice(1, -1) : value;
        key = '';
        value = '';
        inValue = false;
      } else {
        value += ch;
      }
    }
  }
  const t = out.security.toUpperCase();
  out.security = t === '' || t === 'NOPASS' ? 'none' : t;
  out.hidden = out.hidden.toLowerCase() === 'true' ? 'true' : 'false';
  return out;
}

