function parseVcard(payload) {
  const out = { name: '', org: '', phone: '', email: '', address: '' };
  if (!payload.toUpperCase().startsWith('BEGIN:VCARD')) return out;
  const parts = (text) => {
    const list = [];
    let cur = '';
    let escaped = false;
    for (const ch of text) {
      if (escaped) {
        cur += ch === 'n' || ch === 'N' ? '\n' : ch;
        escaped = false;
      } else if (ch === '\\') escaped = true;
      else if (ch === ';') {
        list.push(cur.trim());
        cur = '';
      } else cur += ch;
    }
    list.push(cur.trim());
    return list;
  };
  const joined = (text, sep) => parts(text).filter((p) => p !== '').join(sep);
  let family = '';
  let given = '';
  const lines = payload.replace(/\r?\n[ \t]/g, '').split(/\r?\n/);
  for (const line of lines) {
    const colon = line.indexOf(':');
    if (colon < 1) continue;
    const prop = line.slice(0, colon).split(';')[0].split('.').pop().toUpperCase();
    const value = line.slice(colon + 1);
    const first = { FN: 'name', TEL: 'phone', EMAIL: 'email' }[prop];
    if (first && out[first] === '') out[first] = joined(value, ' ');
    else if (prop === 'ORG' && out.org === '') out.org = joined(value, ', ');
    else if (prop === 'ADR' && out.address === '') out.address = joined(value, ', ');
    else if (prop === 'N') [family = '', given = ''] = parts(value);
  }
  if (out.name === '') out.name = [given, family].filter((p) => p !== '').join(' ');
  return out;
}
